import{_ as n,l as s,o as e,c as i,v as r,p as l,x as t,d as p,i as d,S as P}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"背包 FPTAS","description":"","frontmatter":{"title":"背包 FPTAS","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/knapsack-fptas.md","filePath":"cs/knapsack-fptas.md","lastUpdated":1789023840000}'),c={name:"cs/knapsack-fptas.md"};function h(m,a,_,S,T,f){const o=s("Mermaid");return e(),i("div",null,[a[1]||(a[1]=r('<h1 id="背包-fptas" tabindex="-1">背包 FPTAS <a class="header-anchor" href="#背包-fptas" aria-label="Permalink to &quot;背包 FPTAS&quot;">​</a></h1><div class="epigraph"><p>0-1 背包伪多项式 $O(nW)$ 或 $O(nV)$；按价值缩放丢掉低位，$(1-\\varepsilon)$ 近似且时间 $\\mathrm{poly}(n,1/\\varepsilon)$。</p><footer>—— 据 Ibarra and Kim, Fast Approximation Algorithms for the Knapsack and Sum of Subset Problems, 1975；CLRS 第 35.5 节；[背包](/cs/knapsack) 整理</footer></div><p>上一课<a href="/cs/lp-rounding">LP 舍入</a>依赖间隙。背包有 FPTAS：任意 \\(\\varepsilon\\)，多项式于 \\(n\\) 与 \\(1/\\varepsilon\\)。主干背包 DP \\(\\Theta(nW)\\)，\\(W\\) 大则非多项式于输入位数。缺口是缩放。不重写 0-1 转移。后课局部搜索最大割。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>价值 \\(v_i\\)，容量 \\(W\\)。DP 按容量或按价值。FPTAS：令 \\(K=\\varepsilon v_{\\max}/n\\)，把 \\(v_i\\) 换成 \\(\\lfloor v_i/K\\rfloor\\)，对价值做 DP，容量仍精确检查。相对误差 \\(\\le\\varepsilon\\)。时间 \\(O(n^3/\\varepsilon)\\) 量级（随实现）。</p><p>缺口是缩放，不是贪性价比（那不是 FPTAS，最坏可差）。</p><h3 id="不是所有-npc-都有-fptas" tabindex="-1">不是所有 NPC 都有 FPTAS <a class="header-anchor" href="#不是所有-npc-都有-fptas" aria-label="Permalink to &quot;不是所有 NPC 都有 FPTAS&quot;">​</a></h3><p>强 NPC（三维匹配等）无 FPTAS（除非 P=NP）。背包弱 NPC，伪多项式 \\(\\Rightarrow\\) 常有 FPTAS。</p><p><span class="marginnote">Ibarra–Kim 1975。CLRS 35.5。后课最大割局部搜索 2-近似/期望。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>找 \\(v_{\\max}\\)。缩放。价值 DP：\\(O(n^2/\\varepsilon)\\) 状态级。还原选品。</p>',11)),(e(),l(P,null,{default:t(()=>[d(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20V%5B%22%E4%BB%B7%E5%80%BC%20v_i%22%5D%20--%3E%20SC%5B%22%E9%99%A4%20K%20%E5%8F%96%E6%95%B4%22%5D%0A%20%20SC%20--%3E%20DP%5B%22%E4%BB%B7%E5%80%BC%20DP%22%5D%0A%20%20DP%20--%3E%20EPS%5B%22(1-%CE%B5)%20%E8%BF%91%E4%BC%BC%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>完全背包、分数背包更易，点名。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>每个物品价值误差 \\(\\lt K\\)，最多 \\(n\\) 件，总误差 \\(\\lt \\varepsilon v_{\\max}\\le\\varepsilon\\,\\mathrm{OPT}\\)（若 OPT \\(\\ge v_{\\max}\\)）。容量约束未放松。与伪多项式：状态值域变成 \\(O(n^2/\\varepsilon)\\)。与 PTAS：FPTAS 要 \\(\\mathrm{poly}(n,1/\\varepsilon)\\)，PTAS 允许 \\(n^{f(1/\\varepsilon)}\\)。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写多维背包。不写 EPTAS。后课默认：0-1 背包有 FPTAS。下一课局部搜索与最大割。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>缩放价值 + DP = FPTAS。</li><li>弱 NPC 才有此路。</li><li>贪心性价比不是 FPTAS。</li><li>出处：Ibarra and Kim, 1975；CLRS 第 35.5 节。</li></ul>',7))])}const v=n(c,[["render",h]]);export{u as __pageData,v as default};
